import{z as l,x as s,o as A,c as d,q as t,j as i,D as a,d as B,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"加密市场的制度","description":"","frontmatter":{"title":"加密市场的制度","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-crypto-regime.md","filePath":"quant/gm-crypto-regime.md","lastUpdated":1791413859000}'),p={name:"quant/gm-crypto-regime.md"};function m(D,E,u,C,c,h){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="加密市场的制度" tabindex="-1">加密市场的制度 <a class="header-anchor" href="#加密市场的制度" aria-label="Permalink to &quot;加密市场的制度&quot;">​</a></h1><div class="epigraph"><p>法币市场的制度回答两个问题——谁保护订单、谁保证结算；加密市场把两个答案都交还给交易者自己：跨所价差可以长期存在，账本余额不等于手里的资产。</p><footer>—— 据 Makarov and Schoar, Journal of Financial Economics, 2020；MiCA 公开文本口径整理</footer></div><p><a href="/quant/gm-india">上一课</a>把结算纪律写成现金流。加密市场走到这套对照的边界上：结算极快、制度极薄。区域单元到此结束，本课是「区域」的最后一站——它不是第六个法币市场，而是前五个市场每条规则的否定式：没有订单保护、没有统一磁带、没有中央托管，托管本身就是对手风险。本课写这套「薄制度」的运行机制与尽职调查清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一个缺口是场所碎片化的极端版：几百个场所各自撮合，价格可以长期不一致。法币市场的碎片化有订单保护兜底，跨所价差被机械规则压住；加密没有这层兜底，价差由资本管制与提币延迟保护——管制时期某些市场对美元的溢价可以持续存在且幅度可观（Makarov and Schoar 2020 的核心发现）。第二个缺口是数据：没有监管口径的统一磁带，跨所聚合完全自建，而且聚合前要先过刷量过滤——交易所报告的成交量含大量自成交与激励刷出的水分（Cong 等对加密交易量水分的估计）。第三个缺口是托管：CEX 的成交发生在链下账本，你的「资产」是对交易所的债权；储备证明与客户资产隔离因此成为与费率同级的尽调项，而不是合规装饰。第四个缺口是结算腿：法币出入金与稳定币通道各有自己的信用与延迟，波动最剧烈时恰恰最不可用。</p><p><span class="marginnote">「刷量」翻译成白话：交易所或做市商自己跟自己成交，把成交量报表做大，好上榜、拉客户、骗排名。所以「日成交 10 亿美元」的交易所，真实撮合量可能只有零头——研究加密市场流动性，第一道工序不是计算，而是挤水分。</span></p><p><span class="marginnote">「成交即结算」在加密市场是直觉错误：链下账本的成交要在链上提币才算拿到资产，而提币排队与链上费用在剧烈波动时最贵——把账本余额当头寸，是把 IOU 当资产记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单四项，全部自建。数据：多所聚合要带时戳对齐与异常剔除，刷量过滤先于任何统计量——直接用交易所报告量做的「流动性」研究基本不可比。场所与费用：CEX 的 maker-taker 分层与量档折扣在结构上与法币市场同构，费用调整后的最优同样不等于展示最优（<a href="/quant/maker-taker">maker-taker</a> 的口径原样适用）；DEX 的池价是另一套机制，滑点与池深代替价差。托管与对手：储备证明、隔离条款、提币演练按对手方归档，头寸上限按对手风险而非市场风险设限。监管口径：欧盟以 MiCA 建立成体系框架，美国的口径长期停在执法与个案，同一策略在不同辖区面对的许可与披露要求不同——按运营主体所在辖区归档。</p><p><span class="marginnote">「资金费率」给个数字感觉：永续合约通常每 8 小时结算一次，费率 0.01% 是中性区常见值，极端行情可到 0.5% 以上——持有一个三倍杠杆的多头仓，一次结算可能被收掉自有资金的 1.5%（名义本金的 0.5%）。七乘二十四市场里的「日内季节性」，很大一块就长在这些固定时点上。</span></p>',10)),(A(),i(o,null,{default:a(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CEX%5B%22CEX%EF%BC%9A%E9%93%BE%E4%B8%8B%E8%B4%A6%E6%9C%AC%E6%92%AE%E5%90%88%22%5D%20--%3E%20LEDGER%5B%22%E8%B4%A6%E6%9C%AC%E4%BD%99%E9%A2%9D%EF%BC%9A%E5%AF%B9%E4%BA%A4%E6%98%93%E6%89%80%E7%9A%84%E5%80%BA%E6%9D%83%22%5D%0A%20%20LEDGER%20--%3E%20WD%5B%22%E6%8F%90%E5%B8%81%EF%BC%9A%E9%93%BE%E4%B8%8A%E8%85%BF%22%5D%0A%20%20WD%20--%3E%20SPREAD%5B%22%E8%B7%A8%E6%89%80%E4%BB%B7%E5%B7%AE%EF%BC%9A%E5%8F%97%E7%AE%A1%E5%88%B6%E4%B8%8E%E6%8F%90%E5%B8%81%E5%BB%B6%E8%BF%9F%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20CEX%20--%3E%20POR%5B%22%E5%82%A8%E5%A4%87%E8%AF%81%E6%98%8E%E4%B8%8E%E9%9A%94%E7%A6%BB%E6%89%98%E7%AE%A1%22%5D%0A%20%20AGG%5B%22%E8%B7%A8%E6%89%80%E6%95%B0%E6%8D%AE%E8%81%9A%E5%90%88%22%5D%20--%3E%20WT%5B%22%E5%88%B7%E9%87%8F%E8%BF%87%E6%BB%A4%E5%85%88%E4%BA%8E%E7%BB%9F%E8%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"薄制度把两类风险从「尾部」提回「常态」。其一，对手风险常态化：托管混同或挪用不是极端情形而是历史上的重复事件，主要交易所倒闭后客户资产全额取回并不保证——对手限额与多所分散是仓位管理的一部分，不是运维偏好。其二，套利即流动性提供：跨所价差的收窄者承担提币延迟与链上费用，价差宽度反映的是这两项成本加管制约束，不是「非理性」；把价差当免费午餐，等于把保护价差的摩擦当零。其三，七乘二十四无收盘重构了日内结构：没有官方开盘收盘，「日内季节性」由资金费率时点与全球交易时段重构，按法币市场日历做的日内统计要整体重写。不这么做会错在哪：用法币市场的「制度兜底」假设交易加密资产，三个缺口同时敞开——价差误判、数据失真、对手敞口无界。",-1)),E[5]||(E[5]=e("p",null,"在 CEX 买入的资产从成交到真正到手要经过哪几关、每关可能卡住什么，这条托管链回答的是「什么时候才算你的」：",-1)),(A(),i(o,null,{default:a(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20Trade%5B%22%E9%93%BE%E4%B8%8B%E6%88%90%E4%BA%A4%E6%92%AE%E5%90%88%22%5D%20--%3E%20Ledger%5B%22%E9%93%BE%E4%B8%8B%E8%B4%A6%E6%9C%AC%20%E8%AE%B0%E4%BD%A0%E7%9A%84%E4%BD%99%E9%A2%9D%22%5D%0A%20%20Ledger%20--%3E%20IOU%5B%22%E6%AD%A4%E9%98%B6%E6%AE%B5%E8%B5%84%E4%BA%A7%E6%98%AF%E5%AF%B9%E4%BA%A4%E6%98%93%E6%89%80%E7%9A%84%E5%80%BA%E6%9D%83%22%5D%0A%20%20IOU%20--%3E%20REQ%5B%22%E5%8F%91%E8%B5%B7%E6%8F%90%E5%B8%81%E7%94%B3%E8%AF%B7%22%5D%0A%20%20REQ%20--%3E%20Queue%7B%22%E6%8F%90%E5%B8%81%E6%8E%92%E9%98%9F%20%E9%99%90%E9%A2%9D%20%E5%AE%A1%E6%A0%B8%22%7D%0A%20%20Queue%20--%20%22%E5%8D%A1%E4%BD%8F%22%20--%3E%20Stuck%5B%22%E8%B5%84%E4%BA%A7%E4%BB%8D%E5%9C%A8%E4%BA%A4%E6%98%93%E6%89%80%22%5D%0A%20%20Queue%20--%20%22%E6%94%BE%E8%A1%8C%22%20--%3E%20Chain%5B%22%E9%93%BE%E4%B8%8A%E8%BD%AC%E8%B4%A6%20%E7%9F%BF%E5%B7%A5%E8%B4%B9%E4%B8%8E%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20Chain%20--%3E%20Wallet%5B%22%E8%87%AA%E6%89%98%E7%AE%A1%E9%92%B1%E5%8C%85%20%E6%89%8D%E7%AE%97%E5%88%B0%E6%89%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">常见误区：初学者容易以为「交易所里的币就是我的币」。实际上在提币之前，它更像银行存款——你持有的是对交易所的索取权。银行挤兑的剧本在交易所同样成立：所有人同时提币时，排队长度本身就是风险信号，这也是「提币演练」被列为尽调项的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写代币定价与链上数据工程（另课对象），不写各辖区的合规报备细节；MiCA 落地细则在滚动执行，清单按当期文本重读。稳定币作为结算工具的信用风险单列，不与法币清算混谈——后者是下一课的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加密制度是法币规则的否定式：无订单保护、无统一磁带、无中央托管。</li><li>跨所价差受资本管制与提币延迟保护，是摩擦的定价而非免费机会。</li><li>交易所报告量含刷量水分，聚合研究先过滤再统计。</li><li>账本余额是对交易所的债权；储备证明、隔离与对手限额是仓位管理的一部分。</li><li>费用分层与法币市场同构，费用调整后的最优照旧替代展示最优。</li><li>出处：Makarov and Schoar, <em>Journal of Financial Economics</em>, 2020；Cong 等（Crypto Wash Trading）；MiCA 公开文本口径。</li></ul>',5))])}const g=l(p,[["render",m]]);export{f as __pageData,g as default};
